INSERT [profile].[Introduction] ([Id], [ProfileId]) VALUES (N'e083d12e-c1f3-4a30-999e-f685f1f7f8ef', N'e060f977-1ea5-4a83-8f51-7aec420ae7f8')
INSERT [profile].[IntroductionTranslation] ([IntroductionId], [LanguageCode], [Title], [Motto], [Description]) VALUES (N'e083d12e-c1f3-4a30-999e-f685f1f7f8ef', N'PL', N'.NET Developer', N'Łączę systemy. Rozwiązuję problemy.', N'Tworzę i rozwijam aplikacje w ekosystemie .NET — od backendu i API po rozwiązania webowe i desktopowe. Łączę systemy biznesowe, pracuję z bazami danych i projektuję komunikację między usługami. Ważne są dla mnie zrozumienie problemu, czytelny kod i architektura, która ułatwia dalszy rozwój. Pomagam zarówno przy nowych projektach, jak i przy utrzymaniu oraz modernizacji istniejących aplikacji.')
GO
INSERT [profile].[IntroductionTranslation] ([IntroductionId], [LanguageCode], [Title], [Motto], [Description]) VALUES (N'e083d12e-c1f3-4a30-999e-f685f1f7f8ef', N'EN', N'.NET Developer', N'I connect systems. I solve problems.', N'I build and develop applications in the .NET ecosystem — from backend and APIs to web and desktop solutions. I connect business systems, work with databases and design communication between services. What matters to me is understanding the problem, readable code and an architecture that makes further development easier. I help with both new projects and the maintenance and modernization of existing applications.')
