INSERT [profile].[Project] ([Id], [ProfileId], [Name], [CodeUrl], [Order]) VALUES (N'05f8c543-fbe7-4dd0-a566-db813b3dcea9', N'e060f977-1ea5-4a83-8f51-7aec420ae7f8', N'Portfolio', N'https://github.com/WiktorWijata/Portfolio', 1)
INSERT [profile].[ProjectTranslation] ([ProjectId], [LanguageCode], [Description], [Goal], [Solution], [ArchitectureCaption], [ArchitectureDiagramLabel]) VALUES (N'05f8c543-fbe7-4dd0-a566-db813b3dcea9', N'PL', N'Strona wizytówka prezentująca moje umiejętności, doświadczenie oraz projekty. Treść na stronę zarządzana jest przez autorski CMS.', N'Prezentacja doświadczenia i projektów oraz samodzielna aktualizacja treści portfolio.', N'Interfejs w React i TypeScript połączony z backendem .NET i bazą MSSQL.', N'Uproszczony schemat komponentów. HTTP opisuje komunikację, strzałki między warstwami — zależności kodu.', N'React komunikuje się przez HTTP z Portfolio.Api. API udostępnia moduły Profile i Notifications przez ich kontrakty. Każdy moduł ma Application, Domain, Persistence oraz Infrastructure.')
INSERT [profile].[ProjectTranslation] ([ProjectId], [LanguageCode], [Description], [Goal], [Solution], [ArchitectureCaption], [ArchitectureDiagramLabel]) VALUES (N'05f8c543-fbe7-4dd0-a566-db813b3dcea9', N'EN', N'A portfolio website showcasing my skills, experience, and projects. The site content is managed by a custom CMS.', N'Presenting my experience and projects, and updating the portfolio content myself.', N'A React and TypeScript interface connected to a .NET backend and an MSSQL database.', N'A simplified component diagram. HTTP describes communication; arrows between layers show code dependencies.', N'React communicates over HTTP with Portfolio.Api. The API exposes the Profile and Notifications modules through their contracts. Each module has Application, Domain, Persistence and Infrastructure layers.')
