INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'731a36d0-3e57-42cb-ab45-27bd8efd734c', N'05f8c543-fbe7-4dd0-a566-db813b3dcea9', 1)
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'731a36d0-3e57-42cb-ab45-27bd8efd734c', N'PL', N'Clean Architecture', N'Profile i Notifications mają własne projekty Contracts, Application, Domain, Persistence i Infrastructure. Kontrolery korzystają wyłącznie z kontraktów modułów (IProfileModule, INotificationsModule); host API rejestruje ich implementacje. Wspólne BuildingBlocks dostarczają podstawy techniczne.')
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'731a36d0-3e57-42cb-ab45-27bd8efd734c', N'EN', N'Clean Architecture', N'Profile and Notifications each have their own Contracts, Application, Domain, Persistence and Infrastructure projects. Controllers depend only on the module contracts (IProfileModule, INotificationsModule); the API host registers their implementations. Shared BuildingBlocks provide the technical foundation.')
INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'6dafdeb8-134d-49ce-8ed2-91abe0de78a2', N'05f8c543-fbe7-4dd0-a566-db813b3dcea9', 2)
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'6dafdeb8-134d-49ce-8ed2-91abe0de78a2', N'PL', N'CQRS z MediatR', N'Każdy odczyt to osobne zapytanie (np. GetExperiencesQuery, GetProjectsQuery) z własnym handlerem, a przygotowanie wiadomości obsługuje PrepareNotificationToSendCommand. Handlery działają przez repozytoria. Rozdział komend i zapytań nie oznacza osobnych baz danych.')
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'6dafdeb8-134d-49ce-8ed2-91abe0de78a2', N'EN', N'CQRS with MediatR', N'Every read is its own query (e.g. GetExperiencesQuery, GetProjectsQuery) with a dedicated handler, and preparing a message is handled by PrepareNotificationToSendCommand. Handlers work through repositories. Separating commands and queries does not mean separate databases.')
INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'a411ade1-9ceb-44c7-9569-cbf04c9ff0cc', N'05f8c543-fbe7-4dd0-a566-db813b3dcea9', 3)
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'a411ade1-9ceb-44c7-9569-cbf04c9ff0cc', N'PL', N'DDD — model domeny i tłumaczenia', N'Agregaty (m.in. Profile, Project, Experience) dziedziczą po AggregateRoot<Guid>. Treści językowe leżą w osobnych tabelach tłumaczeń, a encja sama wybiera właściwe (GetTranslation) z powrotem do PL, gdy brakuje wersji. Interfejsy repozytoriów są w Domain, ich implementacje w Persistence.')
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'a411ade1-9ceb-44c7-9569-cbf04c9ff0cc', N'EN', N'DDD — domain model and translations', N'Aggregates (among them Profile, Project and Experience) derive from AggregateRoot<Guid>. Language-specific content lives in separate translation tables, and the entity picks the right one itself (GetTranslation), falling back to PL when a version is missing. Repository interfaces live in Domain, their implementations in Persistence.')
INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'ec37586e-9c39-4cea-8a67-69ff250c033b', N'05f8c543-fbe7-4dd0-a566-db813b3dcea9', 4)
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'ec37586e-9c39-4cea-8a67-69ff250c033b', N'PL', N'Język i kontekst żądania', N'Język wybiera nagłówek Accept-Language — adresy API nie mają parametru języka. ICallerContext podaje język bieżącego żądania, a ICurrentTenant profil, którego dane są zwracane; handlery łączą jedno z drugim.')
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'ec37586e-9c39-4cea-8a67-69ff250c033b', N'EN', N'Language and request context', N'The language comes from the Accept-Language header — API routes have no language parameter. ICallerContext supplies the current request''s language and ICurrentTenant the profile whose data is returned; handlers combine the two.')
INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'3ffddc3a-6508-4126-9980-e94250e62ac9', N'05f8c543-fbe7-4dd0-a566-db813b3dcea9', 5)
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'3ffddc3a-6508-4126-9980-e94250e62ac9', N'PL', N'Zaplecze techniczne', N'API konfiguruje Hangfire z magazynem SQL Server, logowanie Serilog i limit żądań formularza kontaktowego. EF Core korzysta z osobnych kontekstów modułów, rejestrowanych ze wspólnym connection stringiem.')
INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'3ffddc3a-6508-4126-9980-e94250e62ac9', N'EN', N'Technical backbone', N'The API configures Hangfire with a SQL Server store, Serilog logging and a rate limit for the contact form requests. EF Core uses a separate context per module, registered with a shared connection string.')
